Approach: chunk ids are deterministic and each chunk carries a content hash, so synchronisation is a set comparison: embed what is missing or changed, delete what disappeared. Note the limitation of fixed windows: inserting a word near the start shifts every later window, so most chunks change; structure-aware chunking (by heading or clause) localises edits better.

**`ingest.py`**

```python
from __future__ import annotations

import hashlib
import re
from dataclasses import dataclass
from typing import Protocol


@dataclass(frozen=True, slots=True)
class Chunk:
    chunk_id: str
    doc_id: str
    index: int
    text: str
    start: int
    end: int
    content_hash: str


def chunk_words(doc_id: str, text: str, size: int = 120, overlap: int = 20) -> list[Chunk]:
    if size <= 0 or not 0 <= overlap < size:
        raise ValueError("need size > 0 and 0 <= overlap < size")
    spans = [m.span() for m in re.finditer(r"\S+", text)]
    chunks: list[Chunk] = []
    for i, first in enumerate(range(0, len(spans), size - overlap)):
        window = spans[first:first + size]
        start, end = window[0][0], window[-1][1]
        body = text[start:end]
        digest = hashlib.sha256(body.encode()).hexdigest()
        chunks.append(Chunk(f"{doc_id}#{i}", doc_id, i, body, start, end, digest))
        if first + size >= len(spans):
            break
    return chunks


class Embedder(Protocol):
    async def embed(self, texts: list[str]) -> list[list[float]]: ...


class VectorStore:
    """In-memory stand-in for a vector database: chunk_id -> (content_hash, vector)."""

    def __init__(self) -> None:
        self._rows: dict[str, tuple[str, list[float]]] = {}

    def hash_of(self, chunk_id: str) -> str | None:
        row = self._rows.get(chunk_id)
        return row[0] if row else None

    def ids_for(self, doc_id: str) -> set[str]:
        prefix = f"{doc_id}#"
        return {cid for cid in self._rows if cid.startswith(prefix)}

    def upsert(self, chunk: Chunk, vector: list[float]) -> None:
        self._rows[chunk.chunk_id] = (chunk.content_hash, vector)

    def delete(self, chunk_ids: set[str]) -> None:
        for cid in chunk_ids:
            self._rows.pop(cid, None)

    def __len__(self) -> int:
        return len(self._rows)


@dataclass(frozen=True, slots=True)
class SyncReport:
    added: int
    updated: int
    unchanged: int
    deleted: int


class IndexSync:
    def __init__(self, embedder: Embedder, store: VectorStore, *, size: int = 120,
                 overlap: int = 20) -> None:
        self._embedder, self._store = embedder, store
        self._size, self._overlap = size, overlap

    async def sync(self, doc_id: str, text: str) -> SyncReport:
        chunks = chunk_words(doc_id, text, self._size, self._overlap)
        existing = self._store.ids_for(doc_id)
        todo = [c for c in chunks if self._store.hash_of(c.chunk_id) != c.content_hash]
        if todo:
            vectors = await self._embedder.embed([c.text for c in todo])
            for chunk, vec in zip(todo, vectors, strict=True):
                self._store.upsert(chunk, vec)
        stale = existing - {c.chunk_id for c in chunks}
        self._store.delete(stale)
        added = sum(1 for c in todo if c.chunk_id not in existing)
        return SyncReport(added=added, updated=len(todo) - added,
                          unchanged=len(chunks) - len(todo), deleted=len(stale))
```

**`test_ingest.py`**

```python
import asyncio

import pytest

from ingest import IndexSync, VectorStore, chunk_words


def words(n: int, prefix: str = "w") -> str:
    return " ".join(f"{prefix}{i}" for i in range(n))


class CountingEmbedder:
    def __init__(self) -> None:
        self.texts_embedded = 0

    async def embed(self, texts):
        self.texts_embedded += len(texts)
        return [[float(len(t)), 1.0] for t in texts]


def test_chunks_cover_the_text_and_overlap_exactly():
    text = words(100)
    chunks = chunk_words("d", text, size=20, overlap=5)
    assert [c.chunk_id for c in chunks] == [f"d#{i}" for i in range(len(chunks))]
    assert all(text[c.start:c.end] == c.text for c in chunks)
    for left, right in zip(chunks, chunks[1:]):
        assert left.text.split()[-5:] == right.text.split()[:5]
    assert chunks[0].text.split()[0] == "w0" and chunks[-1].text.split()[-1] == "w99"


def test_last_window_is_not_duplicated():
    chunks = chunk_words("d", words(50), size=20, overlap=5)
    assert [(c.text.split()[0], c.text.split()[-1]) for c in chunks] == [
        ("w0", "w19"), ("w15", "w34"), ("w30", "w49")]


@pytest.mark.parametrize("size, overlap", [(0, 0), (10, 10), (10, -1), (10, 11)])
def test_invalid_parameters(size, overlap):
    with pytest.raises(ValueError):
        chunk_words("d", "a b c", size=size, overlap=overlap)


def test_empty_text_has_no_chunks():
    assert chunk_words("d", "   \n ", size=10, overlap=2) == []


def test_identical_text_gives_identical_hashes():
    a = chunk_words("d", words(40), 20, 5)
    b = chunk_words("d", words(40), 20, 5)
    assert [c.content_hash for c in a] == [c.content_hash for c in b]


def test_first_sync_embeds_everything_second_sync_embeds_nothing():
    emb, store = CountingEmbedder(), VectorStore()
    sync = IndexSync(emb, store, size=20, overlap=5)
    first = asyncio.run(sync.sync("d", words(100)))
    assert (first.added, first.updated, first.unchanged, first.deleted) == (7, 0, 0, 0)
    assert emb.texts_embedded == 7 and len(store) == 7
    second = asyncio.run(sync.sync("d", words(100)))
    assert (second.added, second.updated, second.unchanged, second.deleted) == (0, 0, 7, 0)
    assert emb.texts_embedded == 7


def test_editing_the_last_word_re_embeds_one_chunk():
    emb, store = CountingEmbedder(), VectorStore()
    sync = IndexSync(emb, store, size=20, overlap=5)
    asyncio.run(sync.sync("d", words(100)))
    edited = words(99) + " CHANGED"
    report = asyncio.run(sync.sync("d", edited))
    assert (report.added, report.updated, report.unchanged) == (0, 1, 6)
    assert emb.texts_embedded == 8


def test_shrinking_a_document_deletes_orphans():
    emb, store = CountingEmbedder(), VectorStore()
    sync = IndexSync(emb, store, size=20, overlap=5)
    asyncio.run(sync.sync("d", words(100)))
    report = asyncio.run(sync.sync("d", words(50)))
    assert report.deleted == 4 and report.unchanged == 3
    assert store.ids_for("d") == {"d#0", "d#1", "d#2"}


def test_other_documents_are_untouched():
    emb, store = CountingEmbedder(), VectorStore()
    sync = IndexSync(emb, store, size=20, overlap=5)
    asyncio.run(sync.sync("a", words(50, "a")))
    asyncio.run(sync.sync("ab", words(50, "b")))
    asyncio.run(sync.sync("a", words(10, "a")))
    assert store.ids_for("ab") == {"ab#0", "ab#1", "ab#2"}
